window.ScripturaLexicons.BDAG_PART_0297 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-01\" data-source=\"BDAG\" data-search=\"πραϋπαθία, ας, ἡ substantivo feminino mansidão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πραϋπαθία, ας, ἡ</td><td>substantivo feminino</td><td>mansidão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-02\" data-source=\"BDAG\" data-search=\"πραΰς, πραεῖα, πραΰ adjetivo manso, humilde, gentil, afável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πραΰς, πραεῖα, πραΰ</td><td>adjetivo</td><td>manso, humilde, gentil, afável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-03\" data-source=\"BDAG\" data-search=\"πραΰτης, ητος, ἡ substantivo feminino mansidão, humildade, cortesia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πραΰτης, ητος, ἡ</td><td>substantivo feminino</td><td>mansidão, humildade, cortesia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-04\" data-source=\"BDAG\" data-search=\"πρέπω verbo convir, ser apropriado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρέπω</td><td>verbo</td><td>convir, ser apropriado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-05\" data-source=\"BDAG\" data-search=\"πρεσβεία, ας, ἡ substantivo feminino embaixador, embaixada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρεσβεία, ας, ἡ</td><td>substantivo feminino</td><td>embaixador, embaixada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-06\" data-source=\"BDAG\" data-search=\"πρεσβευτής, οῦ, ὁ substantivo masculino embaixador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρεσβευτής, οῦ, ὁ</td><td>substantivo masculino</td><td>embaixador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-07\" data-source=\"BDAG\" data-search=\"πρεσβεύω verbo ser embaixador, representar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρεσβεύω</td><td>verbo</td><td>ser embaixador, representar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-08\" data-source=\"BDAG\" data-search=\"πρεσβυτέριον, ου, τό substantivo neutro conselho de anciãos, presbitério BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρεσβυτέριον, ου, τό</td><td>substantivo neutro</td><td>conselho de anciãos, presbitério</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-09\" data-source=\"BDAG\" data-search=\"πρεσβύτερος, α, ον adjetivo; substantivo mais velho, ancião, presbítero BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρεσβύτερος, α, ον</td><td>adjetivo; substantivo</td><td>mais velho, ancião, presbítero</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-10\" data-source=\"BDAG\" data-search=\"πρεσβύτης, ου, ὁ substantivo masculino ancião, homem idoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρεσβύτης, ου, ὁ</td><td>substantivo masculino</td><td>ancião, homem idoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-11\" data-source=\"BDAG\" data-search=\"πρεσβῦτις, ιδος, ἡ substantivo feminino mulher idosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρεσβῦτις, ιδος, ἡ</td><td>substantivo feminino</td><td>mulher idosa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-12\" data-source=\"BDAG\" data-search=\"πρήθω verbo inchar, distender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρήθω</td><td>verbo</td><td>inchar, distender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-13\" data-source=\"BDAG\" data-search=\"πρηνής, ές, adjetivo prostrado, de cabeça, de bruços BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρηνής, ές,</td><td>adjetivo</td><td>prostrado, de cabeça, de bruços</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-14\" data-source=\"BDAG\" data-search=\"πρίζω verbo serrar, serrar ao meio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρίζω</td><td>verbo</td><td>serrar, serrar ao meio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-15\" data-source=\"BDAG\" data-search=\"πρίν advérbio, conjunção, preposição antes, anteriormente, antes que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρίν</td><td>advérbio, conjunção, preposição</td><td>antes, anteriormente, antes que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-16\" data-source=\"BDAG\" data-search=\"Πρίσκα nome próprio feminino Prisca, Priscila BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πρίσκα</td><td>nome próprio feminino</td><td>Prisca, Priscila</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-17\" data-source=\"BDAG\" data-search=\"πρίω remissão ver πρίζω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρίω</td><td>remissão</td><td>ver πρίζω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-18\" data-source=\"BDAG\" data-search=\"πρό preposição antes de, diante de, acima de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρό</td><td>preposição</td><td>antes de, diante de, acima de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-19\" data-source=\"BDAG\" data-search=\"προαγαπάω verbo amar antes, amar primeiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προαγαπάω</td><td>verbo</td><td>amar antes, amar primeiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0297-20\" data-source=\"BDAG\" data-search=\"προάγω verbo conduzir, levar para fora, preceder, ir adiante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προάγω</td><td>verbo</td><td>conduzir, levar para fora, preceder, ir adiante</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0297-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πραϋπαθία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πραϋπαθία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πραΰς</span>, <span class=\"greek\">πάθος</span> por intermédio de <span class=\"greek\">παθεῖν</span> [aor. de <span class=\"greek\">πάσχω</span>; Philo, Abr. 213; Hesíquio explica-a empregando as palavras <span class=\"greek\">ἡσυχία</span> e <span class=\"greek\">πραΰτης</span> como sinônimos, portanto o oposto de uma atitude dominadora) mansidão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:11</a> (v.l. <span class=\"greek\">πραότητα</span>). Também <span class=\"greek\">πραϋπάθεια</span> ITr 8:1. Sobre a grafia, cf. <span class=\"greek\">κακοπάθεια</span>,-<span class=\"greek\">ία</span> v. Kühner-Bl. II 276, 1. V. também ADebrunner, Griech. Wortbildungslehre 1917, §299.—DELG s.v. <span class=\"greek\">πάσχω</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πραΰς, πραεῖα, πραΰ</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πραΰς</span>, <span class=\"greek\">πραεῖα</span>, <span class=\"greek\">πραΰ</span> (Hom.+; Crinagoras [I a.C. / I d.C.] em Anth. Pal. 10, 24, 4; 16, 273, 6; PGM 4, 1046; LXX; Jos., Ant. 19, 330; SibOr 4, 159 com v.l.) gen. <span class=\"greek\">πραέως</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:4</a>; cf. W-S. §9, 5 p. 87; Kühner-Bl. I §126, 3 n. 9; B-D-F §46, 3; Mayser I/2 §68, 2, 1e p. 55f) e <span class=\"greek\">πραέος</span>; pl. <span class=\"greek\">πραεῖς</span> (sobre <span class=\"greek\">πραΰς</span> e <span class=\"greek\">πρᾶος</span> Kühner-Bl. I 532f; B-D-F §26 ap.; Mlt-H. 160; Thackeray 180f; Crönert 290, 2.—Mas em nossa literatura <span class=\"greek\">πρᾶος</span> [2 Macc 15:12; Philo; Jos., C. Ap. 1, 267] ocorre somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:29</a> v.l.), relativo a não se deixar impressionar excessivamente por um sentimento da própria importância, gentil, humilde, atencioso, manso no sentido favorável mais antigo (cf. OED s.v. 1b; Pind., P. 3, 71 descreve o governante de Siracusa como alguém que é <span class=\"greek\">π</span>. para com seus cidadãos, aparentemente o povo comum [Gildersleeve]), despretensioso D 3:7a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:5</a> (Zech 9:9). Com <span class=\"greek\">ταπεινός</span> (Is 26:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:29</a> (THaering, Schlatter Festschr. 1922, 3–15; MRist, JR 15, ’35, 63–77). Com <span class=\"greek\">ἡσύχιος</span> (e ocasionalmente outras características) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:4</a>; 1 Cl 13:4 (cf. Is 66:2); B 19:4; Hm 5, 2, 3; 6, 2, 3; 11:8 (Leutzsch, Hermas 452, n. 122). Entre as qualidades exigidas dos dirigentes da igreja D 15:1. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὀργὰς</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">πραεῖς</span> mansos diante da ira deles IEph 10:2 (cf. PLond 1912, 83f <span class=\"greek\">εἵνα</span> <span class=\"greek\">Ἀλεξανδρεῖς</span> <span class=\"greek\">πραέως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φιλανθρόπως</span> <span class=\"greek\">προσφέροντε</span> [=<span class=\"greek\">προσφέρωνται</span>] <span class=\"greek\">Ἰουδαίοις</span>=afirmamos, portanto, que os alexandrinos devem comportar-se com bondade e benevolência para com os judeus [41 d.C.]).—<span class=\"greek\">οἱ</span> <span class=\"greek\">πραεῖς</span> (Ps 36:11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:5</a> (WClarke, Theology 47, ’44, 131–33; NLohfink, Die Besänftigung des Messias, Gedanken zu Ps. 37 [Mt]: FKamphous Festschr., ed. JHainz et al. ’97, 75–87; Betz, SM 124–27); D 3:7b.—LMarshall, Challenge of NT Ethics ’47, 80ff; 300ff.—DELG s.v. <span class=\"greek\">πρᾶος</span>. M-M. EDNT. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πραΰτης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πραΰτης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πραΰς</span>; Appian, Bell. Civ. 4, 123 §518 <span class=\"greek\">διὰ</span> <span class=\"greek\">πραΰτητα</span>; Aesop, Fab. 168 P.=94b H.//247 Ch.//H-H. 178; CIG 2788; LXX [Thackeray p. 91; 181]; Sextus 545) e o grego mais antigo (desde Thu., também Appian, Basil. 1 §5; PLond 1912, 101 [41 d.C.]; Philo; Jos., Bell. 6, 383, Ant. 19, 334; IPol 2:1; 6:2), <span class=\"greek\">πραότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (assim em Ign. e Hermas, enquanto no NT <span class=\"greek\">πραΰτης</span> é a forma predominante e <span class=\"greek\">πραότης</span> aparece como v.l.; para a bibliografia, v. <span class=\"greek\">πραΰς</span>), a qualidade de não se deixar impressionar excessivamente por um sentimento da própria importância, gentileza, humildade, cortesia, consideração, mansidão no sentido favorável mais antigo (v. <span class=\"greek\">πραΰς</span>) com <span class=\"greek\">ἐπιείκεια</span> (Plut., Caesar 734 [57], e, ocasionalmente, outras qualidades, como Lucian, Somn. 10; v. também Plut., Pyrrh. 398[23, 3]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:1</a> (RLeivestad, NTS 12, ’66, 156–64); 1 Cl 30:8; Dg 7:4; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:2</a>; 1 Cl 21:7. Com outras virtudes (Ps 44:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:2</a>; B 20:2; D 5:2; Hm 12, 3, 1. <span class=\"greek\">ἐν</span> <span class=\"greek\">π</span>. com mansidão ou em mansidão (Sir 3:17; 4:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:25</a>; IPol 2:1; 6:2; com humildade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:21</a>; 3:13 (<span class=\"greek\">ἐν</span> <span class=\"greek\">πραΰτητι</span> <span class=\"greek\">σοφίας</span> em sábia mansidão; cf. Appian, Bell. Civ. 3, 79 §323 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σοφίᾳ</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πραότητι</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">εἰρήνῃ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>. 1 Cl 61:2. Também <span class=\"greek\">μετὰ</span> <span class=\"greek\">π</span>. (assim em PLond acima) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:16</a>; Hm 5, 2, 6. Como característica de um bispo ITr 3:2 (como virtude política, v. LRobert, Hellenica 13, ’65, 223). O diabo é frustrado pela humildade 4:2. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">πραΰτητος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>.—AvHarnack, ‘Sanftmut, Huld und Demut’ in der alten Kirche: JKaftan Festschr. 1920, 113ff; JdeRomilly, La douceur dans la pensée grecque ’79; RAC III 206–31.—DELG s.v. <span class=\"greek\">πρᾶος</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρέπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρέπω</span> (Hom.+ em vários sentidos), convir, ser decoroso/adequado (Pind.+) imperf. 3ª pess. sing. <span class=\"greek\">ἔπρεπεν</span>: <span class=\"greek\">τοιοῦτος</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ἔπρεπεν</span> <span class=\"greek\">ἀρχιερεύς</span> convinha que tivéssemos tal sumo sacerdote <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:26</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:1</a>. <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">πρεπέτω</span> nada vos seja agradável IEph 11:2.—A construção impess. <span class=\"greek\">πρέπει</span> <span class=\"greek\">τινί</span> convém a alguém (X., Hell. 4, 1, 37; TestAbr B 14 p. 119, 3 [Stone p. 86] <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πρέπει</span> <span class=\"greek\">δόξα</span>; ApcEsdr 7:16; ApcMos 43) <span class=\"greek\">καθὼς</span> <span class=\"greek\">πρέπει</span> <span class=\"greek\">ἁγίοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:3</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">πρέπει</span> <span class=\"greek\">ἀγαπῶντι</span> B 4:9. Com dat. e seguido de inf. (Chariton 7, 6, 12; Philo, Leg. All. 1, 48 <span class=\"greek\">πρέπει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">φυτεύειν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:10</a>; IEph 4:1; IMg 3:1; ITr 12:2; IPol 5:2. Seguido de inf., caso em que o dat. deve ser suprido ISm 11:2; IPol 7:2.—<span class=\"greek\">πρέπον</span> <span class=\"greek\">ἐστίν</span> é conveniente, apropriado, correto (POxy. 120, 24 <span class=\"greek\">ὡς</span> <span class=\"greek\">πρέπον</span> <span class=\"greek\">ἐστίν</span>; 1 Macc 12:11; 3 Macc 7:13; Just., A I, 3, 1) com dat. de pessoa e seguido de inf. (Isocr., Ep. 5, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:15</a>; IRo 10:2; IPhld 10:1. Seguido de inf. e com dat. a suprir IEph 2:2; IMg 3:2; 4:1; ISm 7:2. Com ac. e seguido de inf. (Lysias 19, 59) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:13</a>.—MPohlenz, <span class=\"greek\">Τὸ</span> <span class=\"greek\">πρέπον</span>: NGG ’33, 53–92.—B. 641. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρεσβεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρεσβεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πρεσβεύω</span>; Aeschyl. et al. em vários sentidos, incluindo ‘embaixada’ Aristoph., Pla.), abstrato pelo concreto, embaixador, embaixadores (Aristoph., X., Pla.+; inscrições, papiros; Orig., C. Cels. 8, 6, 13) <span class=\"greek\">π</span>. <span class=\"greek\">ἀποστέλλειν</span> (SIG 412, 6 e outros [índice IV p. 526a]; cf. 2 Macc 4, 11; Philo, Leg. ad Gai. 239; Jos., Ant. 4, 296) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:32</a>; 19:14. <span class=\"greek\">πρεσβεύειν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πρεσβείαν</span> viajar como embaixador de Deus IPhld 10:1 (<span class=\"greek\">πρεσβεύειν</span> <span class=\"greek\">πρεσβείαν</span> como Philo, Congr. Erud. Gr. 111).—DELG s.v. <span class=\"greek\">πρέσβυς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρεσβευτής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρεσβευτής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πρεσβεύω</span>; Thu., Pla. et al.; inscrições, papiros), embaixador, conjectura de RBentley em lugar de <span class=\"greek\">πρεσβύτης</span> (v. esse lema) Phlm 9.—DELG s.v. <span class=\"greek\">πρέσβυς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρεσβεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρεσβεύω</span> fut. <span class=\"greek\">πρεσβεύσω</span>; 1º aor. <span class=\"greek\">ἐπρέσβευσα</span> (Trag., Hdt. et al., sentido primário ‘ser mais velho’ ou ‘estar na primeira categoria’), ser embaixador/enviado, viajar/trabalhar como embaixador (assim Aristoph., X., Pla. et al.; inscrições, papiros; ApcSed 14:1 p. 135, 35 Ja. <span class=\"greek\">πρέσβευσαι</span> ‘sê meu porta-voz’; Philo; Jos., Ant. 12, 163f, Vi. 65. Empregado especialmente acerca dos legados do imperador: Magie 89; Dssm., LO 320 [LAE 378f]; v. também SEG XXXIX, 1865 para inscrições) <span class=\"greek\">πέμπειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">πρεσβεύσοντα</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> enviar alguém como representante de alguém Pol 13:1. <span class=\"greek\">πρεσβεύειν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πρεσβείαν</span> IPhld 10:1, v. <span class=\"greek\">πρεσβεία</span>. Paulo fala de seu trabalho apostólico como <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">πρεσβεύειν</span> trabalhar como embaixador de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:20</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:20</a> (<span class=\"greek\">πρεσβεύειν</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>: OGI 339, 6; SIG 591, 5; 656, 19; 805, 7ff; sobre o papel mediador dos enviados, v. CBreytenbach, Versöhnung ’89, 64–66).—M-M. DELG s.v. <span class=\"greek\">πρέσβυς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρεσβυτέριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρεσβυτέριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πρεσβύτερος</span>), grupo administrativo que se ocupa dos interesses de uma comunidade específica, conselho de anciãos</p><p class=\"entry-text\">ⓐ Acerca do supremo conselho judaico em Jerusalém, em nossa literatura geralmente chamado <span class=\"greek\">συνέδριον</span> (Schürer II 206–8) <span class=\"greek\">τὸ</span> <span class=\"greek\">πρεσβυτέριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.66\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:66</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀρχιερεὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:5</a>.</p><p class=\"entry-text\">ⓑ Como conselho relacionado à administração das congregações cristãs, incluindo todos os <span class=\"greek\">πρεσβύτεροι</span> (v. <span class=\"greek\">πρεσβύτερος</span> 2b), presbitério. Assim, exceto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:14</a> (JJeremias, ZNW 48, ’57, 127–32: ‘honra’ ou ‘privilégio de um presbítero’; cf. Sus 50 [Teodocião] e rabinos), em nossa literatura somente em Ign.: com <span class=\"greek\">ἐπίσκοπος</span> e <span class=\"greek\">διάκονοι</span> IMg 13:1; ITr 7:2; IPhld 4; 7:1; ISm 12:2. Com <span class=\"greek\">ἐπίσκοπος</span> IEph 2:2; 20:2; IMg 2; ITr 13:2. O <span class=\"greek\">ἐπίκοπος</span> e <span class=\"greek\">πρ</span>. pertencem um ao outro como as cordas à harpa IEph 4:1. Deve-se obedecer ao <span class=\"greek\">πρ</span>. como aos apóstolos ITr 2:2; ISm 8:1. Os apóstolos são descritos como <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐκκλησίας</span> IPhld 5:1.—Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρεσβύτερος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρεσβύτερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (Hom.+; comp. de <span class=\"greek\">πρέσβυς</span>)</p><p class=\"entry-text\">① Relativo a ter idade relativamente avançada, mais velho, velho</p><p class=\"entry-text\">ⓐ Acerca de uma pessoa individual, o mais velho de dois <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πρ</span>. (cf. Aelian, VH 9, 42; TestJob 15:2 <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀδελφῷ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πρεσβυτέρῳ</span>; JosAs; Just., A II, 6, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:25</a>; acerca de Manassés (com Efraim) B 13:5. Em contraste com a geração mais jovem <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span> os mais velhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:9</a>. Oposto a <span class=\"greek\">οἱ</span> <span class=\"greek\">νεανίσκοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:17</a> (Jo 3:1). Oposto a <span class=\"greek\">νεώτεροι</span> (v. <span class=\"greek\">νεός</span> 3a<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:1</a> (conselho semelhante, contendo um contraste entre <span class=\"greek\">πρ</span>. e <span class=\"greek\">νεώτ</span>., de inscrições e literatura em MDibelius, Hdb. ad loc.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:5</a> (embora aqui os <span class=\"greek\">πρεσβύτεροι</span> não sejam somente as pessoas mais velhas, mas ao mesmo tempo os ‘presbíteros’; v. 2b<span class=\"greek\">β</span>). O mesmo duplo sentido encontra-se para <span class=\"greek\">πρεσβύτεροι</span> em 1 Cl 1:3 ao lado de <span class=\"greek\">νέοι</span>, enquanto em 3:3; 21:6, ao lado da mesma palavra, predomina a noção de ser velho (como Jos., C. Ap. 2, 206). Sobre a passagem controvertida Hv 3, 1, 8 (<span class=\"greek\">οἱ</span> <span class=\"greek\">νεανίσκοι</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span>), cf. MDibelius, Hdb. ad loc.—Fem. <span class=\"greek\">πρεσβυτέρα</span> mulher velha (ou mais velha) (oposto a <span class=\"greek\">νεωτέρα</span>, como Gen 19:31) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:2</a>.—Sem referência a pessoas mais jovens, com desaparecimento completo do aspecto comparativo: <span class=\"greek\">πρεσβύτερος</span> um homem idoso (Jos., Ant. 13, 226; 292 [como testemunha de acontecimentos do passado, como Ps.-Pla., Virt. 3, 377b; 4, 377c]) Hv 3, 12, 2; cf. 3, 11, 3. A igreja personificada é chamada <span class=\"greek\">λίαν</span> <span class=\"greek\">πρεσβυτέρα</span> muito velha 3, 10, 3; cf. 3, 11, 2. Ela aparece como <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. a mulher idosa 2, 1, 3; 3, 1, 2; 3, 10, 6; 9 e tem <span class=\"greek\">τὰς</span> <span class=\"greek\">τρίχας</span> <span class=\"greek\">πρεσβυτέρας</span> os cabelos de uma mulher idosa 3, 10, 4; 5; 3, 12, 1.</p><p class=\"entry-text\">ⓑ Acerca de um período de tempo (Petosiris, Fgm. 3 e 4 mencionam <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span> e <span class=\"greek\">οἱ</span> <span class=\"greek\">νεώτεροι</span>. Em ambos os casos, o contexto mostra que a referência é a astrólogos de épocas anteriores e mais recentes) <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span> os homens de outrora, nossos antepassados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:2</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">παράδοσις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρεσβυτέρων</span> a tradição dos antigos (cf. Iambl., Vi. Pyth. 35, 253 <span class=\"greek\">τῶν</span> <span class=\"greek\">π</span>. <span class=\"greek\">συγγράμματα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:3</a>, 5 (ELohse, D. Ordination im Spätjudentum u. NT, ’51, 50–56: eruditos).</p><p class=\"entry-text\">② Titular de um cargo (cf. lat. senator), ancião, presbítero</p><p class=\"entry-text\">ⓐ Entre os judeus (a congregação de uma sinagoga de Jerusalém empregava <span class=\"greek\">πρεσβύτεροι</span> para designar seus dirigentes antes de 70 d.C.: SEG VIII, 170, 9; cf. Dssm., LO 378–80 [LAE 439–41]).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Para membros de conselhos locais em cidades individuais (cf. Josh 20:4; Ruth 4:2; 2 Esdr 10:14; Jdth 8:10; 10:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:3</a>; 1 Cl 55:4.—Schürer II, 185.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Para membros de um grupo no Sinédrio (Schürer II, 206–8; JJeremias, Jerusalem z. Zt. Jesu II B 1: Die gesellschaftl. Oberschicht 1929, 88ff). São mencionados juntamente com os outros grupos: <span class=\"greek\">ἀρχιερεῖς</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:5</a> apresenta <span class=\"greek\">ἄρχοντες</span> em lugar disso), <span class=\"greek\">γραμματεῖς</span>, <span class=\"greek\">πρεσβύτεροι</span> (a ordem nem sempre é a mesma) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:21</a>; 26:3 v.l.; 27:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:31</a>; 11:27; 14:43, 53; 15:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:22</a>; 20:1.—Somente <span class=\"greek\">ἀρχιερεῖς</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:8</a> apresenta em lugar disso <span class=\"greek\">ἄρχοντες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span>) e <span class=\"greek\">πρεσβύτεροι</span> (<span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span>: cf. Ex 19:7; Num 11:16b, 24; 1 Macc 7:33; 12:35; Just., D. 40, 4 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:23</a>; 26:3, 47, 59 v.l.; 27:1, 3, 12, 20; 28:(11), 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:52</a> (aqui, excepcionalmente, <span class=\"greek\">οἱ</span> <span class=\"greek\">στρατηγοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:23</a>; 23:14; 25:15; cf. 24:1. Também <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἱερεῖς</span> GPt 7:25 (para esta combinação, cf. Jos., Ant. 11, 83; 12, 406).—Somente <span class=\"greek\">πρεσβύτεροι</span> e <span class=\"greek\">γραμματεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.57\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:57</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:12</a>.—O uso de <span class=\"greek\">πρεσβύτερος</span> como título entre os judeus da diáspora aparece bastante tarde, excetuadas as alusões na LXX (cf. Schürer III/1, 102; MAMA III [Cilícia], 344; 448 [cf. ZNW 31, ’32, 313f]. Se <span class=\"greek\">πρεσβύτερος</span> deve ser entendido como título nas inscrições romanas mais antigas [CIJ 378] [assim CIJ p. lxxxvi], permanece duvidoso).</p><p class=\"entry-text\">ⓑ Entre os cristãos (quanto ao emprego da palavra como título, deve-se ter em mente não somente o costume judaico, mas também seu uso como termo técnico entre os <span class=\"greek\">ἔθνη</span>, em conexão com associações dos ‘velhos’ [FPoland, Geschichte des griech. Vereinswesens 1909, 98ff] e para designar funcionários tanto civis como religiosos [Dssm., B 153ff=BS 154–57, NB 60ff=BS 233–35, também LO 315, 5; HHausschildt, ZNW 4, 1903, 235ff; MStrack, ibid. 213ff; HLietzmann, ZWT 55, 1914, 116–32 [=Kl. Schr. I ’58, 156–69]; MDibelius, excurso sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:17ff</a>; RAlastair-Campbell, The Elders, Seniority within Earliest Christianity ’94.].—BGU 16, 6 [159 d.C.] <span class=\"greek\">πρεσβύτεροι</span> <span class=\"greek\">ἱερεῖς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">Σοκνοπαίου</span>; 347, 6; PVindBosw 1, 31 [87 d.C.].—Como título honorífico: Iren. 4, 26, 5 [Harv. II 238, 3]. A palavra inglesa ‘priest’ provém de <span class=\"greek\">πρεσβύτερος</span> por intermédio do lat. presbyter; o uso cristão posterior é em grande parte, senão inteiramente, responsável por este desenvolvimento; v. OED s.v. ‘priest’ B).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:30</a>; 14:23; 15:2, 4, 6, 22f; 16:4 (em todas as passagens de Ac 15 e 16 faz-se menção de <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀπόστολοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span> na igreja de Jerusalém); 20:17; 21:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:17</a>, 19 (Nicol. Dam.: 90 Fgm. 103a Jac. <span class=\"greek\">νεωτέρῳ</span> <span class=\"greek\">πρεσβυτέρου</span> <span class=\"greek\">καταμαρτυρεῖν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔξεστι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:1</a>, 5 (v. 1a acima); 1 Cl 44:5; 47:6; 54:2; 57:1. WWrede, Untersuchungen zum 1 Cl 1891, 8ff.—Segundo 2 Cl 17:3, 5, a exortação e a pregação nos cultos da igreja figuravam entre seus deveres.—Em Ign. os <span class=\"greek\">πρεσβύτεροι</span> vêm depois do bispo, ao qual estão subordinados IMg 2; 3:1; 6:1, ou entre o bispo e os diáconos IPhld inscr.; 10:2; IPol 6:1, ou a posição superior do bispo em comparação com eles é evidenciada de alguma outra maneira ITr 3:1; 12:2 (v. <span class=\"greek\">πρεσβυτέριον</span> b; cf. Hippol., Ref. 9, 12, 22).—Policarpo — um <span class=\"greek\">ἐπίσκοπος</span>, segundo o título da epístola que leva seu nome — agrupa-se com <span class=\"greek\">πρεσβύτεροι</span> em Pol inscr. e, além disso, considera pressuposta a presença de presbíteros em Filipos (ao lado dos diáconos, embora nenhum <span class=\"greek\">ἐπίσκοπος</span> seja mencionado; cf. Hdb. sobre Pol inscr.) Pol 5:3.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. A maneira exata como devemos entender as palavras <span class=\"greek\">ὁ</span> <span class=\"greek\">πρεσβύτερος</span>, aplicadas a si mesmo pelo autor das duas menores cartas joaninas 2J 1; 3J 1, permanece duvidosa. Mas, em qualquer caso, pretende-se indicar uma posição de grande dignidade, o presbítero.—HWindisch, excurso sobre 3J, fim; ESchwartz, Über den Tod der Söhne Zebedaei 1904, 47; 51; HWendt, ZNW 23, 1924, 19; EKäsemann, ZTK 48, ’51, 292–311; DWatson, NTS 35, ’89, 104–30, análise retórica de 2J.—<span class=\"greek\">ὁ</span> <span class=\"greek\">πρ</span>. e <span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. são mencionados por Papias nestas passagens muito discutidas: 2:3, 4, 5, 7, 14, 15. Para parte da bibliografia, v. a nota na tradução de JKleist ’48, p. 207 n. 18.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Em Rv há 24 anciãos sentados em tronos ao redor do trono de Deus; constituem um conselho celestial de anciãos (cf. Is 24:23) 4:4, 10; 5:5–14; 7:11, 13; 11:16; 14:3; 19:4. Os anciãos têm sido entendidos como seres humanos glorificados de alguma espécie ou divindades astrais (ou anjos) (para as várias opiniões, v. RCharles, ICC Rv I 128–33; JMichl, D. 24 Ältesten in d. Apk. d. hl. J. ’38); o número 24 tem sido relacionado com o seguinte: as 24 classes sacerdotais dos judeus (1 Ch 24:7–18; Jos., Ant. 7, 365–67), cujos chefes eram chamados ‘anciãos’ (Yoma 1, 5; Tamid 1, 1; Middoth 1, 8); as 24 estrelas que, segundo a crença babilônica, situavam-se metade ao norte e metade ao sul do zodíaco (Diod S 2, 31, 4; POsl 4, 19: HGunkel, Z. religionsgesch. Verständnis des NT 1903, 42f; Boll 35f); as 24 horas do dia, representadas como velhos com vestes resplandecentes e coroas (segundo o Test. de Adão [ed. CBezold, TNöldeke Festschr. 1906, 893–912]: JWellhausen, Analyse der Offb. Joh. 1907, p. 9, 1; NMorosof, Offb. Joh. 1912, 32); os 24 Yazatas na organização política dos deuses no céu, segundo o pensamento persa (Bousset). É certamente uma questão em aberto se, ou até que ponto, o autor de Rv tinha alguma destas coisas em mente.—Sobre os presbíteros, e especialmente sobre a questão de como <span class=\"greek\">ἐπίσκοπος</span> e <span class=\"greek\">πρεσβύτερος</span> se relacionavam originalmente entre si (questão suscitada particularmente nas pastorais; cf. MDibelius, Hdb. excurso depois de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:7</a> seção 2 [com bibliografia] e antes de 5:17), v. a bibliografia s.v. <span class=\"greek\">ἐπίσκοπος</span>.—BEaston, Pastoral Epistles ’47, 188–97; WMichaelis, Das Ältestenamt ’53; GBornkamm, <span class=\"greek\">πρεσβύτερος</span>; RCampbell, The Elders ’94.—B. 1472. DELG s.v. <span class=\"greek\">πρέσβυς</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρεσβύτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρεσβύτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aeschyl., Hippocr. et al.; IG IV2/1, 123, 120; papiros; LXX; Jos., Bell. 1, 312), homem velho, homem idoso (Philo, Op. M. 105, seguindo Hippocr.: homem de 50–56 anos; Dio Chrys. 57 [74], 10 <span class=\"greek\">πρεσβύτης</span> segue imediatamente a série <span class=\"greek\">παῖς</span>, <span class=\"greek\">μειράκιον</span> <span class=\"greek\">νεανίσκος</span>; Aristoxenus Fgm. 35 apresenta os estágios <span class=\"greek\">νήπιος</span>, <span class=\"greek\">παῖς</span>, <span class=\"greek\">νεανίσκος</span>, <span class=\"greek\">ἀνήρ</span>, <span class=\"greek\">πρεσβύτης</span>; cf. VLeinieks, The City of Dionysos ’96, 199–209) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:2</a>; Phlm 9 (mas muitos aceitam a conjectura de RBentley <span class=\"greek\">πρεσβευτής</span> embaixador, isto é, de Cristo: Lghtf.; W-H., aparato; EHaupt; Lohmeyer; REB; RSV; Goodsp., Probs. 185–87; contra este ponto de vista HermvSoden, MDibelius, Meinertz, NRSV; JBirdsall, NTS 39, ’93, 625–30. Sobre esta passagem, cf. também RSteck, PM 18, 1914, 96–100; 192f; PSchmidt, ibid. 156–58.—Polyaenus 8, 9, 1 <span class=\"greek\">πρεσβύτης</span> e <span class=\"greek\">πρεσβευτής</span> são encontrados como variantes); MPol 7:2 (empregado atributivamente com <span class=\"greek\">ἀνήρ</span>: <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀνήρ</span> como Theophyl. Sim., Ep. 60); Hm 8:10.—FBoll (v. <span class=\"greek\">νεανίας</span>) 116f. DELG s.v. <span class=\"greek\">πρέσβυς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρεσβῦτις, ιδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρεσβῦτις</span>, <span class=\"greek\">ιδος</span>, <span class=\"greek\">ἡ</span> (Aeschyl., Pla.+; talvez CIJ 400 [I a.C.–III d.C.], v. BBrooten, Inscriptional Evidence for Women as Leaders in the Ancient Synagogue: SBLSP 20, ’81, 4; tradução de B: ‘Aqui jaz Sara Ura, anciã [ou mulher idosa]’; Diod S 4, 51, 1; 4 Macc 16:14; Philo, Spec. Leg. 2, 33; Jos., Ant. 7, 142; 186), mulher velha (ou de mais idade), senhora idosa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:3</a>; Hv 1, 2, 2 (<span class=\"greek\">γυνὴ</span> <span class=\"greek\">πρ</span>., como Aeschines 3, 157).—DELG s.v. <span class=\"greek\">πρέσβυς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρήθω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρήθω</span> (Hom. et al.; LXX; Jos. Ant. 3, 271) 1º aor. inf. <span class=\"greek\">πρῆσαι</span> (Num 5:22), part. pass. <span class=\"greek\">πρησθείς</span>; lit. ‘inflar, distender’; pass., inchar <span class=\"greek\">Ἰούδας</span> <span class=\"greek\">πρησθεὶς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span>, <span class=\"greek\">ὥστε</span> … Judas, cuja carne estava tão inchada que … . Papias (3:2); v.l. <span class=\"greek\">ἐπρήσθη</span> <span class=\"greek\">γάρ</span>; outras vv.ll. em Preuschen, Antilegomena, e AHilgenfeld, ZWT 18, 1875, 262–65.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρηνής, ές,</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρηνής</span>, <span class=\"greek\">ές</span>, gen. <span class=\"greek\">οῦς</span> (sobre a forma Schwyzer I 189; Hom. et al.; PGM 4, 194; LXX; Just., D. 90, 5; Mel., P. 26, 184.—X. apresenta <span class=\"greek\">πρανής</span>, que se encontra no uso ático posterior ao lado de <span class=\"greek\">πρηνής</span>), para a frente, prostrado, de cabeça, de bruços <span class=\"greek\">πρηνὴς</span> <span class=\"greek\">γενόμενος</span> estando (caindo) de cabeça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:18</a> (cf. <span class=\"greek\">πρ</span>. <span class=\"greek\">πεσών</span> Theophyl., MPG CXXIII 146; Posid.: 87 Fgm. 5 Jac. <span class=\"greek\">πρ</span>. <span class=\"greek\">προσπεσών</span>; Diod S 34+35, Fgm. 28a <span class=\"greek\">πρηνὴς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>; Appian, Celts 10 <span class=\"greek\">κατέπεσε</span> <span class=\"greek\">πρηνής</span>; Philo, Op. M. 157 <span class=\"greek\">πρηνὲς</span> <span class=\"greek\">πεπτωκός</span>; Jos., Bell. 1, 621 e Vi. 138 <span class=\"greek\">πρ</span>. <span class=\"greek\">πεσών</span>, Bell. 6, 64, Ant. 18, 59; SibOr 4, 110). O sentido inchado, distendido foi proposto pela primeira vez por FChase, JTS 13, 1912, 278–85; 415, e aceito por Harnack, TLZ 37, 1912, 235–37; EbNestle, ZNW 19, 1920, 179f; HWendt e GHoennicke, ad loc.; JMoffatt, trad. 1913; RHarris, AJT 18, 1914, 127–31; Goodsp., Probs. 123–26; L-S-J-M apresenta-o como possibilidade s.v. <span class=\"greek\">πρανής</span>, com referência a <span class=\"greek\">πρησθείς</span>; neste caso seria derivado da raiz <span class=\"greek\">πρη</span>-, <span class=\"greek\">πίμπρημι</span> (v. esse lema), o que é linguisticamente questionável. Faltam outros exemplos de <span class=\"greek\">πρηνής</span> no sentido de ‘inchado’, a menos que se atribua à palavra esse sentido em Wsd 4:19 (assim Goodsp.), mas ‘prostrado e silencioso’ faz bom sentido nesta passagem. Lake (abaixo) assinala os interesses harmonizadores de escritores posteriores como Ps-Zonaras e Euthymius Zigabenus.—O rompimento em consequência de uma queda violenta encontra-se também em Aesop, Fab. 177b H.=181 P.//192 H-H.//142f Ch. <span class=\"greek\">κατακρημνισθεὶς</span> <span class=\"greek\">διερράγη</span>.—V. ainda Zahn, Forsch. VI 1900, 126; 153–55; IX 1916, 331–33; AKnox, JTS 25, 1924, 289f; HCadbury, JBL 45, 1926, 192f; KLake, Beginn. I 5, ’33, 22–30; Beyer, Steinmann e Bruce ad loc.; REB; NRSV.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρίζω</span> (<span class=\"greek\">πρίω</span> ‘serrar’; [Ps.-?]Pla., Theag. 124b; Diod S 3, 27, 3; 4, 76, 5; PHerm 28, 11 <span class=\"greek\">φοίνικες</span> <span class=\"greek\">πεπρισμένοι</span>; Am 1:3; designado como não ático por Pollux 7, 114) ou <span class=\"greek\">πρίω</span> (Trag., Thu. et al.) 1º aor. <span class=\"greek\">ἔπρισα</span> (Sus 59 Theod.; Just., D. 120, 5), pass. <span class=\"greek\">ἐπρίσθην</span> serrar (ao meio) como método de execução (Sus 59 Theod.); segundo a tradição (MartIs 3:14, 16, 19 Gebh. [=Denis p. 113 linhas 18 e 30, p. 114 linha 14]; ViIs rec. Dor. [p. 41, 18 Sch.; Torrey p. 20]; Justin, Dial. 120 et al.; MGaster e BHeller, Monatsschr. f. Gesch. u. Wissensch. des Judent. 80, ’36, 32–44) Isaías morreu desta maneira, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:37</a>.—DELG s.v. <span class=\"greek\">πρίω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρίν</h1><div class=\"entry-meta\"><span>advérbio, conjunção, preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρίν</span> (Hom.+; inscrições, papiros, LXX), lit. adv. de tempo ‘antes, outrora’, depois marcador de um ponto de tempo anterior a outro ponto de tempo, antes</p><p class=\"entry-text\">ⓐ Como conjunção temporal (a tradição manuscrita frequentemente varia entre <span class=\"greek\">πρίν</span>, que é predominantemente ático, e <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἤ</span> [v. <span class=\"greek\">ἤ</span> 2d], que é jônico [Schwyzer II 313] e predomina na koiné [Schwyzer II 656]).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com subj. aor. (Plut., Caes. 735 [58, 2]; Lucian, Ver. Hist. 2, 18) ou opt. (B-D-F §383, 3; Rob. 977) <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἀκουσθῶσι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> Hs 5, 7, 3. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:26</a> é textualmente incerto <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ἴδῃ</span>, mas <span class=\"greek\">ἤ</span> é omitido (cf. Cyr.-Ins. 123 <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἄν</span> com subj. aor.), assim como <span class=\"greek\">ἄν</span> em alguns manuscritos, e uma v.l. apresenta <span class=\"greek\">ἕως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ἴδῃ</span>. Igualmente em 22:34 <span class=\"greek\">ἕως</span>, <span class=\"greek\">ἕως</span> <span class=\"greek\">οὗ</span>, <span class=\"greek\">ἕως</span> <span class=\"greek\">ὅτου</span> também são atestados em lugar de <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἤ</span>; houve intervenção do corretor em todas estas passagens, de modo que a leitura original já não pode ser determinada com certeza.—Somente uma vez com o opt., em discurso indireto depois de um tempo passado (B-D-F §386, 4; Rob. 970) <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κατηγορούμενος</span> <span class=\"greek\">ἔχοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:16</a> (cf. Jos., Ant. 20, 210).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Seguido de ac. e inf. aor. (B-D-F §395; Rob. 977.—Plut., Lysander 448 [27, 1] <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἐπανελθεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἀγησίλαον</span>; Lucian, Dial. Deor. 20, 16 <span class=\"greek\">πρίν</span>; Jos., Ant. 11, 1 <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἤ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18</a> (<span class=\"greek\">πρὶν</span> <span class=\"greek\">ἤ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.58\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:58</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:2</a> (<span class=\"greek\">πρὶν</span> <span class=\"greek\">ἤ</span>); 1 Cl 38:3: Dg 2:3 (<span class=\"greek\">πρὶν</span> <span class=\"greek\">ἤ</span>); 8:1; Hs 9, 16, 3. Também acerca de coisas futuras (Arrian, Ind. 24, 6 <span class=\"greek\">πρὶν</span> <span class=\"greek\">ταχθῆναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φάλαγγα</span>=antes que a falange tenha sido disposta em formação) <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἀλέκτορα</span> <span class=\"greek\">φωνῆσαι</span> antes que o galo tenha cantado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:34</a>, 75; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:30</a> (<span class=\"greek\">πρὶν</span> <span class=\"greek\">ἤ</span>), 72; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.61\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:61</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.49\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:20</a> (Jo 3:4); Hs 9, 26, 6.—Sem o ac., que se subentende pelo contexto (Menand., Epitr. 264 S. [88 Kö.]; 508 S. [332 Kö.]; Diod S 13, 10, 1; 14, 52, 1; Chion, Ep. 4, 4; Ps.-Apollod. 3, 3, 2; Jos., Bell. 6, 213; Just., A I, 4, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:29</a>; Hv 3, 1, 3.</p><p class=\"entry-text\">ⓑ Funciona como prep. com gen. (desde Pind., P. 4, 43, também Plut., Mor. 883b; Arrian, Anab. 3, 18, 6; PGM 7, 418; 420 <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">ἀνατολῆς</span>; En 14:6; Jos., Ant. 4, 269 <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">δυσμῶν</span>; Sus 35a LXX=42 Theod.; para contraste com <span class=\"greek\">πρότερον</span>, cf. o epitáfio <span class=\"greek\">οὐ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θανεῖν</span> <span class=\"greek\">ἄλγεινόν</span>, <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">τό</span> <span class=\"greek\">γε</span> <span class=\"greek\">Μοῖρ</span>’ <span class=\"greek\">ἐπέκλωσεν</span>, | <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἡλικίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γονέων</span> <span class=\"greek\">πρότερον</span> EpigrAnat 13, ’89, 128f, nº 2=morrer não é em si deplorável, pois assim decreta o Destino, mas quando se morre antes de atingir a maturidade e antes dos próprios pais) <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἀλεκτοροφωνίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:34</a> v.l.; <span class=\"greek\">πρὶν</span> <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">εἰμί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.58\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:58</a> v.l.—Até <span class=\"greek\">πρίν</span> com ac. ocorre como v.l. <span class=\"greek\">πρὶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσχα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.55\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:55</a> D; <span class=\"greek\">πρὶν</span> <span class=\"greek\">σάββατον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:42</a> D (cf. B-D-F §395 ap.; JWackernagel, Syntax II2 1928, 215).—ATschuschke, De <span class=\"greek\">πρίν</span> particulae apud scriptores aet. August. prosaicos usu, diss. Bresl. 1913.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πρίσκα</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πρίσκα</span> (<span class=\"greek\">Πρῖσκα</span>? v. B-D-F §41, 3; cf. Mlt-H. 155) e seu dim. <span class=\"greek\">Πρίσκιλλα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Preisigke, Namenbuch. Uma sacerdotisa de Zeus chamada <span class=\"greek\">Πρίσκιλλα</span> é mencionada numa inscrição honorífica da cidade de Olbasa: Ramsay, Phrygia I p. 309 nº 122), Prisca, Priscila, fabricante de tendas (v. <span class=\"greek\">Ἀκύλας</span> e a bibliografia ali indicada), mencionada antes de seu marido na maioria dos casos (Harnack [s.v. ’<span class=\"greek\">Ακ</span>.] conclui daí que ela era uma pessoa mais importante que seu marido e que pode ter desempenhado o papel principal na redação de Hb: ZNW 1, 1900, 16ff.—Em Ramsay, op. cit. p. 637 nº 530 [70–80 d.C.] Julia Severa é mencionada antes de seu marido Tyrronius Rapon, provavelmente porque ela era de posição mais elevada) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:2</a>, 18, 26. As passagens acima mencionadas têm o nome <span class=\"greek\">Πρίσκιλλα</span> (igualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:3</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:19</a> v.l.), mas <span class=\"greek\">Πρίσκα</span> é a forma predominante nas cartas paulinas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:19</a>.—IReimer, Women in the Acts of the Apostles ’95. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρίω</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρίω</span> v. <span class=\"greek\">πρίζω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρό</h1><div class=\"entry-meta\"><span>preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρό</span> prep. com gen. (Hom.+—V. a bibliografia s.v. <span class=\"greek\">ἀνά</span>, início; também Rydbeck 62–77) ‘antes’.</p><p class=\"entry-text\">① Marcador de uma posição à frente de um objeto, diante de, em frente de, junto a <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θύρας</span> junto à porta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:6</a>; cf. 5:23 v.l.; <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυλῶνος</span> 12:14; talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:8</a> pertença aqui (Jesus é a porta, v. 7). <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> (Jos., Bell. 1, 234, Ant. 10, 44): <span class=\"greek\">ὁ</span> <span class=\"greek\">ἱερεὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄντος</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> o sacerdote de (o templo de) Zeus imediatamente fora da (porta da) cidade 14:13 (CIG 2963c <span class=\"greek\">τῆς</span> <span class=\"greek\">μεγάλης</span> <span class=\"greek\">Ἀρτέμιδος</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">πόλεως</span> <span class=\"greek\">ἱερεῖς</span> [restaurado]. Cf. as inscrições semelhantes com <span class=\"greek\">πρὸ</span> <span class=\"greek\">πόλεως</span> 2796; 3194; 3211; BCH 11, 1887 p. 464 nº 29 <span class=\"greek\">ὁ</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">πόλεως</span> <span class=\"greek\">Ἀπόλλων</span> [Tiatira]; TWiegand, SBBerlAk 1906, 259 <span class=\"greek\">Ἀσκληπιοῦ</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">πόλεως</span> [Mileto]; cf. <span class=\"greek\">αἱ</span> <span class=\"greek\">προκαθήμεναι</span> <span class=\"greek\">θεαῖ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> SIG 694, 50f; bibliografia s.v. <span class=\"greek\">Λύστρα</span>).—Em linguagem figurada vívida <span class=\"greek\">ὁ</span> <span class=\"greek\">κριτὴς</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θυρῶν</span> <span class=\"greek\">ἕστηκεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:9</a>. Fig. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">ἔχειν</span>, <span class=\"greek\">λαμβάνειν</span> e <span class=\"greek\">πρὸ</span> <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">εἶναι</span>; sobre estes, v. <span class=\"greek\">ὀφθαλμός</span> 2.—<span class=\"greek\">πρὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τινός</span> (=לִפְנֵי פ׳; v. Johannessohn, Präp. 184f) diante de alguém ou à sua frente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:27</a> (sobre todos os três, cf. Mal 3:1; Ex 23:20; TestAbr A 12 p. 91, 4 [Stone p. 30]; GrBar 1:4); 1:76 v.l.; 9:52; 10:1; 1 Cl 34:3 (cf. Is 62:11); em frente de alguém IEph 15:3 (JosAs 24:6 <span class=\"greek\">πρόκειται</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">ὑμῶν</span>). Com transição para um sentido temporal, antes de <span class=\"greek\">προκηρύξαντος</span> <span class=\"greek\">Ἰωάννου</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εἰσόδου</span> <span class=\"greek\">αὐτοῦ</span> depois de João ter pregado como seu precursor antes de seu aparecimento (isto é, de Jesus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:24</a>.</p><p class=\"entry-text\">② Marcador de um ponto de tempo anterior a outro, anteriormente a, antes de <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀρίστου</span> antes da refeição (X., Cyr. 6, 2, 21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:38</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βαπτίσματος</span> D 7:4a. <span class=\"greek\">πρὸ</span> <span class=\"greek\">χειμῶνος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:21</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάσχα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.55\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:55</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἑορτῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάσχα</span> 13:1. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κατακλυσμοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:38</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">καταβολῆς</span> <span class=\"greek\">κόσμου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:20</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σελήνης</span> 2 Cl 14:1 (v. <span class=\"greek\">ἥλιος</span>). <span class=\"greek\">πρὸ</span> <span class=\"greek\">πάντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:17</a>; cf. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">πάντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:12</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">αἰώνων</span> (Ps 54:20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:7</a>; cf. IEph ins; IMg 6:1. <span class=\"greek\">πρὸ</span> <span class=\"greek\">χρόνων</span> <span class=\"greek\">αἰωνίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:2</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span> Jd 25. <span class=\"greek\">πρὸ</span> <span class=\"greek\">καιροῦ</span> antes do tempo oportuno ou dos últimos tempos (<span class=\"greek\">καιρός</span> 3b; cf. Sir 51:30; Theodor. Prodr. 1, 281 H.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:5</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡμερῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:36</a>; 21:38; Hm 4, 3, 4. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:2</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μεταθέσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:5</a>. Latinismo (sobre o uso do calendário romano entre os gregos, v. Hahn 245; EBickerman, Chronology of the Ancient World2, ’80, 47–51; sobre o cálculo de uma data, 43–44) <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἐννέα</span> <span class=\"greek\">καλανδῶν</span> <span class=\"greek\">Σεπτεμβρίων</span> no dia vinte e quatro de agosto IRo 10:3. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">καλανδῶν</span> <span class=\"greek\">Μαρτίων</span> no dia vinte e três de fevereiro MPol 21 (cf. IPriene 105, 23 <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἐννέα</span> <span class=\"greek\">καλανδῶν</span> <span class=\"greek\">Ὀκτωβρίων</span>).—Sobre a expressão <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἓξ</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάσχα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:1</a>, v. <span class=\"greek\">ἡμέρα</span> 2c e cf. Am 1:1; 4:7. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τριῶν</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">συλληφθῆναι</span> <span class=\"greek\">αὐτόν</span> três dias antes de ele ser preso MPol 5:2. <span class=\"greek\">πρὸ</span> <span class=\"greek\">μιᾶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀζύμων</span> um dia antes da festa dos pães asmos GPt 2:5 (Plut., Lucull. 510 [27, 9] <span class=\"greek\">πρὸ</span> <span class=\"greek\">μιᾶς</span> <span class=\"greek\">νωνῶν</span> <span class=\"greek\">Ὀκτωβρίων</span>, Publ. 101 [9, 8]; Appian, Bell. Civ. 2, 115 §479 <span class=\"greek\">πρὸ</span> <span class=\"greek\">μιᾶς</span> <span class=\"greek\">τοῦδε</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βουλευτηρίου</span>). <span class=\"greek\">πρὸ</span> <span class=\"greek\">μιᾶς</span> (subentenda-se <span class=\"greek\">ἡμέρας</span> [Polyaenus 7, 10 e Just., D. 27, 5 <span class=\"greek\">πρὸ</span> <span class=\"greek\">μιᾶς</span> <span class=\"greek\">ἡμέρας</span>]; cf. Lucian, Alex. 46; Dositheus 40, 2; PGM 13, 350) um dia antes D 7:4b; no dia anterior Hs 6, 5, 3.—Rydbeck 62–77; Mlt-Turner 260.—Com gen. de pron. pessoal (PsSol 1:8 <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἔθνη</span>; Just., D. 16, 4 <span class=\"greek\">πρὸ</span> <span class=\"greek\">αὐτοῦ</span>; PTebt 61b, 384 [118/117 a.C.]) <span class=\"greek\">πρὸ</span> <span class=\"greek\">ὑμῶν</span> (Lev 18:28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:12</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:4</a> D. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἐμοῦ</span> (1 Macc 15:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:7</a>; 10:8 (v. também 1 acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:17</a> (v. AcPlCor 2:4). Cf. 1 Cl 19:1.—<span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> com ac. e inf. (En 9:11; TestAbr A 9 p. 87, 10 [Stone p. 22]; ParJer 7:31; Just., D. 92, 3. Cf. B-D-F §403; Rob. 1074f) <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">αἰτῆσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:8</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:21</a>; 22:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:48</a>; 13:19 (aqui falta o ac., mas pode ser facilmente suprido); 17:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:12</a>; 3:23; B 16:7.</p><p class=\"entry-text\">③ Marcador de precedência em importância ou posição hierárquica (Pind. et al.; papiros; Jos., Ant. 16, 187 <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἐκείνων</span>; Just., A I, 2, 1 <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">ψυχῆς</span>) <span class=\"greek\">πρὸ</span> <span class=\"greek\">παντός</span> acima de tudo, especialmente Pol 5:3. Também <span class=\"greek\">πρὸ</span> <span class=\"greek\">πάντων</span> (Ar. 9, 2; Just., D. 7, 3; POxy 292, 11; 294, 30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:8</a>; D 10:4.—DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προαγαπάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προαγαπάω</span> 1º aor. <span class=\"greek\">προηγάπησα</span> antecipar-se na expressão de afeto, amar antes, amar primeiro <span class=\"greek\">τινά</span> alguém Dg 10:3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0297-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προάγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προάγω</span> imperf. <span class=\"greek\">προῆγον</span>; fut. <span class=\"greek\">προάξω</span>; 2º aor. <span class=\"greek\">προήγαγον</span>; 1º aor. pass. <span class=\"greek\">προήχθην</span> LXX (Hdt.+).</p><p class=\"entry-text\">① Trans., levar ou conduzir de uma posição a outra, assumindo a direção, conduzir adiante, conduzir ou levar para fora <span class=\"greek\">τινά</span> alguém: <span class=\"greek\">προαγαγὼν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἔξω</span> depois de os haver conduzido para fora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:30</a> (Diod S 4, 44, 3 <span class=\"greek\">τῆς</span> <span class=\"greek\">φυλακῆς</span> <span class=\"greek\">προαγαγεῖν</span>=conduzir para fora da prisão). <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">προαγαγεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δῆμον</span> 17:5 (Jos., Ant. 16, 320 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span>). Cf. 12:6 (Jos., Ant. 2, 105 e outros).—Na linguagem do tribunal, levar perante (Jos., Bell. 1, 539, Ant. 16, 393; Just. A I, 21, 3.—<span class=\"greek\">ἐπί</span> 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:26</a>.</p><p class=\"entry-text\">② Intrans., deslocar-se adiante ou à frente, ir antes, abrir caminho, preceder</p><p class=\"entry-text\">ⓐ No espaço <span class=\"greek\">τινά</span> ir à frente de alguém (2 Macc 10:1; B-D-F §150; Rob. 477) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:9</a> (GJs 21:3); 21:9; AcPl Ha 3, 29. Uso abs. (Diod S 17, 19, 1 <span class=\"greek\">προῆγε</span>=ele avançava; Jos., Bell. 1, 673, Ant. 14, 388) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:9</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:9</a> (oposto a <span class=\"greek\">ἀκολουθεῖν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:39</a>. Caminhar à frente dos que vão lentamente e com hesitação <span class=\"greek\">ἦν</span> <span class=\"greek\">προάγων</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἀκολουθοῦντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:32</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">με</span> <span class=\"greek\">προῆγον</span> eles iam à minha frente de cidade em cidade IRo 9:3.—Em linguagem figurada <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">προάγων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μένων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">διδαχῇ</span> todo aquele que vai longe demais e não permanece no ensino 2J 9. Acerca de <span class=\"greek\">πίστις</span> (cf. Aberciusins. 12 <span class=\"greek\">πίστις</span> <span class=\"greek\">προῆγε</span>), que é seguida por <span class=\"greek\">ἐλπίς</span> (<span class=\"greek\">ἐπακολουθεῖν</span>), <span class=\"greek\">προαγούσης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀγάπης</span> o amor abre o caminho Pol 3:3.</p><p class=\"entry-text\">ⓑ No tempo, ir ou vir antes de alguém, com ac. de pessoa <span class=\"greek\">προάγειν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πέραν</span> ir adiante dele à outra margem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:22</a>. <span class=\"greek\">προάξω</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Γαλιλαίαν</span> irei adiante de vós à Galileia 26:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:28</a> (CEvans, JTS 5, ’54, 3–18); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:7</a>. Sem ac. (que pode ser suprido pela oração com <span class=\"greek\">ἕως</span> [cf. SIG 684, 25]) <span class=\"greek\">προάγειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Βηθσαϊδάν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:45</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">τελῶναι</span> <span class=\"greek\">προάγουσιν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> os publicanos entrarão no reino de Deus antes de vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:31</a>. Fig., acerca dos pecados <span class=\"greek\">προάγουσαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κρίσιν</span> eles precedem (os pecadores) ao juízo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:24</a> (cf. Oenomaus em Eus., PE 5, 24, 1 <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κρίσιν</span> <span class=\"greek\">προάγειν</span>=‘comparecer perante o tribunal’).—<span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">προάγοντα</span> tudo o que havia acontecido antes MPol 1:1. <span class=\"greek\">κατά</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">προαγούσας</span> <span class=\"greek\">προφητείας</span> de acordo com as profecias feitas há muito tempo (isto é, em referência a Timóteo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:18</a> (IG XII/3, 247 <span class=\"greek\">τὰ</span> <span class=\"greek\">προάγοντα</span> <span class=\"greek\">ψαφίσματα</span>; PFlor 198, 7 [III d.C.] <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">προάγον</span> <span class=\"greek\">ἔθος</span>; POxy 42, 3 <span class=\"greek\">ἡ</span> <span class=\"greek\">πανήγυρις</span> <span class=\"greek\">προάγουσα</span>; Just., D. 33, 1 <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπαγόμενα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">προάγοντα</span> [no salmo]). <span class=\"greek\">ἀθέτησις</span> <span class=\"greek\">προαγούσης</span> <span class=\"greek\">ἐντολῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:18</a> (<span class=\"greek\">ἀθέτησις</span> 1).—M-M. TW.</p></section></article>"};
